// ROIConfigControl: 380px parameter pane + image/40px zoom strip. Geometry stays in image pixels.
public sealed class GroupRoiEditor:Grid {
 static readonly DependencyProperty HasGeometryProperty=DependencyProperty.RegisterAttached("HasGeometry",typeof(bool),typeof(GroupRoiEditor),new PropertyMetadata(false));
 readonly List<RoiDocument> regions;readonly ListBox list=new(){Tag="GroupRoiList",Height=120};readonly StackPanel values=new();readonly Dictionary<string,TextBox> inputs=new();readonly TextBlock error=new(){Foreground=Brushes.DarkRed,TextWrapping=TextWrapping.Wrap};
 readonly Dictionary<RoiKind,System.Windows.Controls.Primitives.ToggleButton> modeButtons=new();readonly Expander parameters=new(){Header="ROI参数",IsExpanded=false,HorizontalAlignment=System.Windows.HorizontalAlignment.Stretch};readonly RoiSurface surface;bool refreshing;public RoiKind? DrawKind{get;private set;}
 public IReadOnlyList<RoiDocument> Regions=>regions.Select(r=>r with{Vertices=r.Vertices?.ToArray()}).ToArray();public int SelectedIndex=>list.SelectedIndex;public bool ParametersExpanded{get=>parameters.IsExpanded;set=>parameters.IsExpanded=value;}
 public GroupRoiEditor(IEnumerable<RoiDocument> source){regions=source.Select(r=>r with{Vertices=r.Vertices?.ToArray()}).ToList();if(regions.Any(r=>r.CoordinateSpace!=RoiCoordinateSpace.ImagePixels))throw new InvalidOperationException("尚未提供Fixture坐标变换，不能以像素坐标编辑此ROI。");ColumnDefinitions.Add(new(){Width=new GridLength(380)});ColumnDefinitions.Add(new());var left=new StackPanel{Margin=new Thickness(10)};var modes=new WrapPanel();foreach(var (text,kind) in new[]{("矩形",RoiKind.Rectangle),("圆",RoiKind.Circle),("圆环",RoiKind.Annulus),("多边形",RoiKind.Polygon)}){var button=ModeButton(text,kind);modeButtons.Add(kind,button);button.Click+=(_,_)=>TryEdit(()=>{if(button.IsChecked==true)SetDrawKind(kind);else CancelGesture();surface!.Focus();});modes.Children.Add(button);}var roiRow=new DockPanel();roiRow.Children.Add(new TextBlock{Text="ROI",Width=90,VerticalAlignment=VerticalAlignment.Center});roiRow.Children.Add(modes);left.Children.Add(roiRow);list.Visibility=Visibility.Collapsed;left.Children.Add(list);var tools=new StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal};foreach(var text in new[]{"删除","复制"}){var b=new Button{Content=text,Tag=text=="删除"?"GroupRoiDelete":"GroupRoiCopy",MinWidth=65};b.Click+=(_,_)=>TryEdit(()=>{if(text=="删除")DeleteSelected();else CopySelected();});tools.Children.Add(b);}tools.Visibility=Visibility.Collapsed;left.Children.Add(tools);parameters.Content=values;left.Children.Add(parameters);left.Children.Add(error);Children.Add(new ScrollViewer{Content=left,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var right=new DockPanel();SetColumn(right,1);var zoom=new StackPanel{Height=40,Orientation=System.Windows.Controls.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right};surface=new RoiSurface(this){Tag="GroupRoiSurface",Focusable=true};RenderOptions.SetBitmapScalingMode(surface,BitmapScalingMode.NearestNeighbor);foreach(var label in new[]{"+","−","1:1","全屏"}){var button=new Button{Content=label,Width=40,Height=34,Tag="GroupRoiZoom:"+label};button.Click+=(_,_)=>{if(label=="全屏")FullScreen(right);else if(label=="1:1")surface.Fit();else surface.SetScale(surface.Scale*(label=="+"?1.5:0.5));};zoom.Children.Add(button);}DockPanel.SetDock(zoom,Dock.Top);right.Children.Add(zoom);right.Children.Add(surface);Children.Add(right);list.SelectionChanged+=(_,_)=>{if(!refreshing)RefreshFields();};var menu=new ContextMenu();foreach(var label in new[]{"删除","复制"}){var item=new MenuItem{Header=label};item.Click+=(_,_)=>TryEdit(()=>{if(label=="删除")DeleteSelected();else CopySelected();});menu.Items.Add(item);}menu.Opened+=(_,_)=>{if(DrawKind==RoiKind.Polygon)menu.IsOpen=false;};surface.ContextMenu=menu;surface.SizeChanged+=(_,_)=>surface.Fit();RefreshList(regions.Count>0?0:-1);
 }
 System.Windows.Controls.Primitives.ToggleButton ModeButton(string text,RoiKind kind){var button=new System.Windows.Controls.Primitives.ToggleButton{Tag="GroupRoiDraw:"+kind,ToolTip=text,Width=36,Height=34,Margin=new Thickness(0,0,27,0)};var root=new FrameworkElementFactory(typeof(Grid));var background=new FrameworkElementFactory(typeof(System.Windows.Controls.Image));background.Name="Background";background.SetValue(System.Windows.Controls.Image.SourceProperty,Asset("roi_选中但未绘制_bg.png"));background.SetValue(VisibilityProperty,Visibility.Hidden);root.AppendChild(background);var icon=new FrameworkElementFactory(typeof(System.Windows.Controls.Image));icon.Name="Icon";icon.SetValue(WidthProperty,32.0);icon.SetValue(HeightProperty,32.0);string normal=kind switch{RoiKind.Rectangle=>"roi_retangle_normal.png",RoiKind.Circle=>"geometry_circle_clickoff.png",RoiKind.Polygon=>"roi_polygon_normal.png",_=>"roi_circle_normal.png"};string pressed=kind==RoiKind.Circle?"geometry_circle_clickon.png":normal.Replace("normal","click");icon.SetValue(System.Windows.Controls.Image.SourceProperty,Asset(normal));root.AppendChild(icon);var template=new ControlTemplate(typeof(System.Windows.Controls.Primitives.ToggleButton)){VisualTree=root};foreach(var property in new[]{IsMouseOverProperty,System.Windows.Controls.Primitives.ToggleButton.IsCheckedProperty}){var trigger=new Trigger{Property=property,Value=true};trigger.Setters.Add(new Setter(VisibilityProperty,Visibility.Visible,"Background"));template.Triggers.Add(trigger);}var hasGeometry=new Trigger{Property=HasGeometryProperty,Value=true};hasGeometry.Setters.Add(new Setter(System.Windows.Controls.Image.SourceProperty,Asset(pressed),"Icon"));template.Triggers.Add(hasGeometry);button.Template=template;return button;}
 static BitmapImage Asset(string name){var image=new BitmapImage();image.BeginInit();image.UriSource=new Uri(System.IO.Path.Combine(AppContext.BaseDirectory,"ui-assets","wpf","group-"+name));image.CacheOption=BitmapCacheOption.OnLoad;image.EndInit();image.Freeze();return image;}
 void RefreshModes(){foreach(var pair in modeButtons){pair.Value.IsChecked=DrawKind==pair.Key;pair.Value.SetValue(HasGeometryProperty,regions.Any(r=>r.Kind==pair.Key));}}
 void TryEdit(Action edit){try{edit();error.Text="";}catch(Exception e){error.Text=e.Message;}}
 void FullScreen(DockPanel parent){parent.Children.Remove(surface);var window=new Window{Owner=Window.GetWindow(this),WindowStyle=WindowStyle.None,WindowState=WindowState.Maximized,Content=surface,ShowInTaskbar=false};window.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Escape){window.Close();e.Handled=true;}};try{window.ShowDialog();}finally{window.Content=null;parent.Children.Add(surface);surface.Fit();}}
 public void SetImage(GrayImage? image){surface.Image=image is null?null:BitmapSource.Create(image.Width,image.Height,96,96,PixelFormats.Gray8,null,image.Pixels.ToArray(),image.Width);surface.Fit();}
 public void SetDrawKind(RoiKind kind){CommitPending();surface.CancelAll();DrawKind=kind;RefreshModes();}
 public void Select(int index){CommitPending();list.SelectedIndex=index;}
 public void DeleteSelected(){if(SelectedIndex<0)return;regions.RemoveAt(SelectedIndex);RefreshList(Math.Min(SelectedIndex,regions.Count-1));}
 public void CopySelected(){if(SelectedIndex<0)return;if(regions.Count>=8)throw new InvalidOperationException("最多8个ROI");CommitPending();var r=regions[SelectedIndex];regions.Add(r with{Id=Guid.NewGuid().ToString("N"),Vertices=r.Vertices?.ToArray()});RefreshList(regions.Count-1);}
 void RefreshList(int index){refreshing=true;list.ItemsSource=regions.Select((r,i)=>$"ROI {i+1} · {r.Kind}").ToArray();list.SelectedIndex=index;refreshing=false;RefreshFields();}
 void RefreshFields(){RefreshModes();values.Children.Clear();inputs.Clear();if(SelectedIndex>=0){var r=regions[SelectedIndex];var fields=r.Kind switch{RoiKind.Rectangle=>new[]{"CenterX","CenterY","Width","Height","AngleDegrees"},RoiKind.Circle=>new[]{"CenterX","CenterY","Radius"},RoiKind.Annulus=>new[]{"CenterX","CenterY","Radius","InnerRadius"},_=>Array.Empty<string>()};foreach(var key in fields){var row=new DockPanel{Height=32,Margin=new Thickness(0,3,0,0)};row.Children.Add(new TextBlock{Text=key switch{"CenterX"=>"中心 X","CenterY"=>"中心 Y","Width"=>"宽度","Height"=>"高度","Radius"=>"半径","InnerRadius"=>"内半径",_=>"角度"},Width=100,VerticalAlignment=VerticalAlignment.Center});var box=new TextBox{Text=Get(r,key).ToString("G",CultureInfo.InvariantCulture),Tag="GroupRoiField:"+key};box.LostKeyboardFocus+=(_,_)=>{try{CommitPending();error.Text="";}catch(Exception e){error.Text=e.Message;}};inputs.Add(key,box);row.Children.Add(box);values.Children.Add(row);}}surface?.InvalidateVisual();}
 public void CommitPending(){if(SelectedIndex<0)return;var r=regions[SelectedIndex];foreach(var (key,input) in inputs){if(!double.TryParse(input.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out var value)||!double.IsFinite(value))throw new InvalidDataException("ROI包含无效数值："+key);r=Put(r,key,value);}RoiValidator.Validate(r);regions[SelectedIndex]=r;surface.InvalidateVisual();}
 static double Get(RoiDocument r,string key)=>key switch{"CenterX"=>r.CenterX,"CenterY"=>r.CenterY,"Width"=>r.Width,"Height"=>r.Height,"Radius"=>r.Radius,"InnerRadius"=>r.InnerRadius,_=>r.AngleDegrees};
 static RoiDocument Put(RoiDocument r,string key,double value)=>key switch{"CenterX"=>r with{CenterX=value},"CenterY"=>r with{CenterY=value},"Width"=>r with{Width=value},"Height"=>r with{Height=value},"Radius"=>r with{Radius=value},"InnerRadius"=>r with{InnerRadius=value},_=>r with{AngleDegrees=value}};
 public void BeginPointer(Point point){CommitPending();surface.Begin(point);}
 public void UpdatePointer(Point point)=>surface.Update(point);
 public void EndPointer(Point point)=>surface.End(point);
 public void CancelGesture(){surface.CancelAll();RefreshFields();}
 public void CompletePolygon()=>surface.CompletePolygon();
 public void UndoPolygonPoint()=>surface.UndoPolygonPoint();
 sealed class RoiSurface(GroupRoiEditor owner):FrameworkElement {
  static readonly Brush background=new SolidColorBrush(Color.FromRgb(45,45,45)),tile=new SolidColorBrush(Color.FromRgb(60,60,60));
  static readonly Brush blue=new SolidColorBrush(Color.FromRgb(15,106,243)),orange=new SolidColorBrush(Color.FromRgb(247,105,0));
  public BitmapSource? Image;public double Scale{get;private set;}=1;Point offset;Point start;RoiDocument? original,draft;int handle=-1;bool active,panning;Point panStart,panOffset;readonly List<Point2> polygon=new();
  public void Fit(){double w=Image?.PixelWidth??640,h=Image?.PixelHeight??480;Scale=Math.Max(.01,Math.Min(Math.Max(1,ActualWidth)/w,Math.Max(1,ActualHeight)/h));offset=new Point((ActualWidth-w*Scale)/2,(ActualHeight-h*Scale)/2);InvalidateVisual();}
  public void SetScale(double value){var center=ToImage(new Point(ActualWidth/2,ActualHeight/2));Scale=Math.Clamp(value,.01,200);offset=new Point(ActualWidth/2-center.X*Scale,ActualHeight/2-center.Y*Scale);InvalidateVisual();}
  Point ToImage(Point p)=>new((p.X-offset.X)/Scale,(p.Y-offset.Y)/Scale);Point ToView(Point p)=>new(p.X*Scale+offset.X,p.Y*Scale+offset.Y);
  public void ZoomAt(Point view,double factor){var point=ToImage(view);Scale=Math.Clamp(Scale*factor,.01,200);offset=new Point(view.X-point.X*Scale,view.Y-point.Y*Scale);InvalidateVisual();}
  protected override void OnMouseRightButtonUp(MouseButtonEventArgs e){if(owner.DrawKind==RoiKind.Polygon){UndoPolygonPoint();e.Handled=true;return;}base.OnMouseRightButtonUp(e);}
  protected override void OnRender(DrawingContext dc){dc.DrawRectangle(background,null,new Rect(RenderSize));for(double y=0;y<ActualHeight;y+=10)for(double x=0;x<ActualWidth;x+=10)if(((int)(x/10)+(int)(y/10))%2==0)dc.DrawRectangle(tile,null,new Rect(x,y,10,10));dc.PushClip(new RectangleGeometry(new Rect(RenderSize)));if(Image is not null)dc.DrawImage(Image,new Rect(offset,new Size(Image.PixelWidth*Scale,Image.PixelHeight*Scale)));for(int i=0;i<owner.regions.Count;i++)Draw(dc,owner.regions[i],i==owner.SelectedIndex);if(draft is not null)Draw(dc,draft,true);if(polygon.Count>0)for(int i=1;i<polygon.Count;i++)dc.DrawLine(new Pen(blue,1),ToView(new(polygon[i-1].X,polygon[i-1].Y)),ToView(new(polygon[i].X,polygon[i].Y)));dc.Pop();}
  Geometry Shape(RoiDocument r){Geometry g;if(r.Kind==RoiKind.Rectangle){g=new RectangleGeometry(new Rect(r.CenterX-r.Width/2,r.CenterY-r.Height/2,r.Width,r.Height));g.Transform=new RotateTransform(r.AngleDegrees,r.CenterX,r.CenterY);}else if(r.Kind is RoiKind.Circle or RoiKind.Annulus)g=new EllipseGeometry(new Point(r.CenterX,r.CenterY),r.Radius,r.Radius);else{var path=new StreamGeometry();using(var context=path.Open()){var vertices=r.Vertices??[];if(vertices.Count>0){context.BeginFigure(new Point(vertices[0].X,vertices[0].Y),true,true);context.PolyLineTo(vertices.Skip(1).Select(p=>new Point(p.X,p.Y)).ToArray(),true,false);}}g=path;}return g;}
  List<Point> Handles(RoiDocument r){if(r.Kind==RoiKind.Rectangle){var rotation=new RotateTransform(r.AngleDegrees,r.CenterX,r.CenterY);return new[]{new Point(r.CenterX-r.Width/2,r.CenterY-r.Height/2),new Point(r.CenterX+r.Width/2,r.CenterY-r.Height/2),new Point(r.CenterX+r.Width/2,r.CenterY+r.Height/2),new Point(r.CenterX-r.Width/2,r.CenterY+r.Height/2),new Point(r.CenterX,r.CenterY-r.Height/2-20/Scale)}.Select(rotation.Transform).ToList();}if(r.Kind is RoiKind.Circle or RoiKind.Annulus){var points=new List<Point>{new(r.CenterX+r.Radius,r.CenterY)};if(r.Kind==RoiKind.Annulus)points.Add(new(r.CenterX+r.InnerRadius,r.CenterY));return points;}return (r.Vertices??[]).Select(p=>new Point(p.X,p.Y)).ToList();}
  void Draw(DrawingContext dc,RoiDocument r,bool selected){var transform=new MatrixTransform(Scale,0,0,Scale,offset.X,offset.Y);dc.PushTransform(transform);dc.DrawGeometry(null,new Pen(blue,1/Scale),Shape(r));if(r.Kind==RoiKind.Annulus)dc.DrawEllipse(null,new Pen(blue,1/Scale),new Point(r.CenterX,r.CenterY),r.InnerRadius,r.InnerRadius);dc.Pop();if(selected)foreach(var point in Handles(r)){var p=ToView(point);dc.DrawRectangle(orange,new Pen(Brushes.White,1),new Rect(p.X-3,p.Y-3,6,6));}}
  public void Begin(Point p){Cancel();start=p;handle=-1;if(owner.DrawKind is {} kind){if(owner.regions.Count>=8)throw new InvalidOperationException("最多8个ROI");if(kind==RoiKind.Polygon){if(polygon.Count>=32)throw new InvalidOperationException("多边形最多32个点");polygon.Add(new(p.X,p.Y));InvalidateVisual();return;}draft=new(Guid.NewGuid().ToString("N"),kind,p.X,p.Y,1,1,1,0);active=true;return;}
   if(owner.SelectedIndex>=0){original=owner.regions[owner.SelectedIndex];handle=Handles(original).FindIndex(h=>(h-p).Length<=7/Scale);if(handle>=0){active=true;return;}}
   for(int i=owner.regions.Count-1;i>=0;i--){var r=owner.regions[i];if(Shape(r).FillContains(p)||Shape(r).StrokeContains(new Pen(blue,10/Scale),p)){owner.list.SelectedIndex=i;original=r;active=true;return;}}owner.list.SelectedIndex=-1;original=null;
  }
  public void Update(Point p){if(!active)return;double dx=p.X-start.X,dy=p.Y-start.Y;if(draft is not null){draft=draft with{CenterX=(start.X+p.X)/2,CenterY=(start.Y+p.Y)/2,Width=Math.Max(.001,Math.Abs(dx)),Height=Math.Max(.001,Math.Abs(dy)),Radius=Math.Max(.001,Math.Sqrt(dx*dx+dy*dy)/2),InnerRadius=0};if(draft.Kind is RoiKind.Circle or RoiKind.Annulus){draft=draft with{CenterX=start.X,CenterY=start.Y,Radius=Math.Max(.001,Math.Sqrt(dx*dx+dy*dy))};if(draft.Kind==RoiKind.Annulus)draft=draft with{InnerRadius=draft.Radius/2};}}else if(original is {} r){RoiDocument next;if(handle<0)next=r with{CenterX=r.CenterX+dx,CenterY=r.CenterY+dy,Vertices=r.Vertices?.Select(v=>new Point2(v.X+dx,v.Y+dy)).ToArray()};else if(r.Kind is RoiKind.Circle or RoiKind.Annulus){double radius=(p-new Point(r.CenterX,r.CenterY)).Length;next=handle==1?r with{InnerRadius=Math.Clamp(radius,0,r.Radius-.001)}:r with{Radius=Math.Max(radius,r.InnerRadius+.001)};}else if(r.Kind==RoiKind.Polygon){var points=r.Vertices!.ToArray();points[handle]=new(p.X,p.Y);next=r with{Vertices=points};}else if(handle==4)next=r with{AngleDegrees=Math.Atan2(p.Y-r.CenterY,p.X-r.CenterX)*180/Math.PI+90};else{var local=new RotateTransform(-r.AngleDegrees,r.CenterX,r.CenterY).Transform(p);var anchor=Handles(r)[(handle+2)%4];anchor=new RotateTransform(-r.AngleDegrees,r.CenterX,r.CenterY).Transform(anchor);var center=new RotateTransform(r.AngleDegrees,r.CenterX,r.CenterY).Transform(new Point((local.X+anchor.X)/2,(local.Y+anchor.Y)/2));next=r with{CenterX=center.X,CenterY=center.Y,Width=Math.Max(.001,Math.Abs(local.X-anchor.X)),Height=Math.Max(.001,Math.Abs(local.Y-anchor.Y))};}owner.regions[owner.SelectedIndex]=next;}InvalidateVisual();}
  public void End(Point p){if(!active)return;Update(p);if(draft is not null&&(p-start).Length<.001){draft=null;active=false;InvalidateVisual();return;}if(draft is not null){RoiValidator.Validate(draft);owner.regions.Add(draft);draft=null;owner.DrawKind=null;owner.RefreshModes();owner.RefreshList(owner.regions.Count-1);}active=false;original=null;owner.RefreshFields();InvalidateVisual();}
  public void CompletePolygon(){if(polygon.Count<3)throw new InvalidOperationException("多边形至少需要3个点");if(owner.regions.Count>=8)throw new InvalidOperationException("最多8个ROI");var r=new RoiDocument(Guid.NewGuid().ToString("N"),RoiKind.Polygon,0,0,Vertices:polygon.ToArray());RoiValidator.Validate(r);owner.regions.Add(r);polygon.Clear();owner.DrawKind=null;owner.RefreshModes();owner.RefreshList(owner.regions.Count-1);InvalidateVisual();}
  public void UndoPolygonPoint(){if(polygon.Count>0)polygon.RemoveAt(polygon.Count-1);InvalidateVisual();}
  public void CancelAll(){Cancel();polygon.Clear();owner.DrawKind=null;owner.RefreshModes();}
  public void Cancel(){if(active&&original is not null&&owner.SelectedIndex>=0)owner.regions[owner.SelectedIndex]=original;draft=null;original=null;active=false;InvalidateVisual();}
  protected override void OnMouseLeftButtonDown(MouseButtonEventArgs e){base.OnMouseLeftButtonDown(e);Focus();try{owner.CommitPending();if(owner.DrawKind==RoiKind.Polygon&&e.ClickCount==2){CompletePolygon();e.Handled=true;return;}Begin(ToImage(e.GetPosition(this)));if(!active&&owner.DrawKind is null&&Image is not null){panning=true;panStart=e.GetPosition(this);panOffset=offset;}if(active||panning||owner.DrawKind==RoiKind.Polygon)CaptureMouse();e.Handled=true;}catch(Exception error){owner.error.Text=error.Message;}}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(active)Update(ToImage(e.GetPosition(this)));else if(panning){var delta=e.GetPosition(this)-panStart;offset=panOffset+delta;InvalidateVisual();}}
  protected override void OnMouseLeftButtonUp(MouseButtonEventArgs e){base.OnMouseLeftButtonUp(e);try{End(ToImage(e.GetPosition(this)));panning=false;}finally{if(owner.DrawKind!=RoiKind.Polygon)ReleaseMouseCapture();}}
  protected override void OnLostMouseCapture(MouseEventArgs e){base.OnLostMouseCapture(e);panning=false;CancelAll();owner.RefreshFields();}
  protected override void OnMouseWheel(MouseWheelEventArgs e){ZoomAt(e.GetPosition(this),1+Math.Round(e.Delta/120.0,MidpointRounding.AwayFromZero)*0.5);e.Handled=true;}
  protected override void OnKeyDown(System.Windows.Input.KeyEventArgs e){base.OnKeyDown(e);if(e.Key==Key.Escape){CancelAll();ReleaseMouseCapture();owner.RefreshFields();e.Handled=true;}else if(e.Key==Key.Delete){owner.DeleteSelected();e.Handled=true;}else if(e.Key==Key.C&&Keyboard.Modifiers==ModifierKeys.Control){owner.CopySelected();e.Handled=true;}}
 }
}
